//! Small self-contained PRNG (xoshiro256**), seeded from time and pid.

use std::time::{SystemTime, UNIX_EPOCH};

pub struct Rng {
    s: [u64; 4],
}

#[inline]
fn rotl(x: u64, k: u32) -> u64 {
    (x << k) | (x >> (64 - k))
}

impl Rng {
    pub fn new() -> Rng {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0x9e37_79b9_7f4a_7c15);
        let pid = std::process::id() as u64;
        let mut sm = nanos ^ pid.wrapping_mul(0x9e37_79b9_7f4a_7c15) ^ 0x2545_f491_4f6c_dd1d;
        let mut s = [0u64; 4];
        for v in s.iter_mut() {
            // splitmix64
            sm = sm.wrapping_add(0x9e37_79b9_7f4a_7c15);
            let mut z = sm;
            z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
            *v = z ^ (z >> 31);
        }
        Rng { s }
    }

    #[inline]
    pub fn next_u64(&mut self) -> u64 {
        let result = rotl(self.s[1].wrapping_mul(5), 7).wrapping_mul(9);
        let t = self.s[1] << 17;
        self.s[2] ^= self.s[0];
        self.s[3] ^= self.s[1];
        self.s[1] ^= self.s[2];
        self.s[0] ^= self.s[3];
        self.s[2] ^= t;
        self.s[3] = rotl(self.s[3], 45);
        result
    }

    /// Uniform float in [0, 1).
    pub fn gen_f64(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 / (1u64 << 53) as f64
    }

    /// Uniform integer in [min, max).
    pub fn gen_range(&mut self, min: u64, max: u64) -> u64 {
        debug_assert!(min < max);
        min + self.next_u64() % (max - min)
    }

    /// Uniform integer in [min, max].
    pub fn gen_range_inclusive(&mut self, min: u64, max: u64) -> u64 {
        self.gen_range(min, max.wrapping_add(1))
    }

    pub fn gen_bool(&mut self, p: f64) -> bool {
        self.gen_f64() < p
    }

    pub fn choose<'a, T>(&mut self, items: &'a [T]) -> &'a T {
        &items[self.gen_range(0, items.len() as u64) as usize]
    }

    pub fn shuffle<T>(&mut self, items: &mut [T]) {
        for i in (1..items.len()).rev() {
            let j = self.gen_range(0, i as u64 + 1) as usize;
            items.swap(i, j);
        }
    }
}

//! Shared runtime state and helpers used by all modules.

use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::OnceLock;
use std::thread;
use std::time::{Duration, Instant};

use crate::rng::Rng;

pub struct Globals {
    /// Speed factor; all sleeps are divided by this.
    pub speed: f32,
    /// Deadline after which we exit gracefully (checked between printed lines).
    pub deadline: Option<Instant>,
}

pub static GLOBALS: OnceLock<Globals> = OnceLock::new();

/// Remaining number of lines that should print instantly (no delay).
pub static INSTANT_REMAINING: AtomicU64 = AtomicU64::new(0);

pub fn globals() -> &'static Globals {
    GLOBALS.get().expect("globals not initialized")
}

pub fn speed() -> f32 {
    globals().speed
}

/// Everything a module needs while running.
pub struct App {
    pub rng: Rng,
}

impl App {
    pub fn new() -> App {
        App { rng: Rng::new() }
    }
}

/// Sleep for `ms` milliseconds, scaled by the global speed factor.
/// Consumes one "instant line" credit instead of sleeping when available.
pub fn sleep_ms(ms: u64) {
    let scaled = (ms as f32 / speed()) as u64;
    if INSTANT_REMAINING
        .fetch_update(Ordering::SeqCst, Ordering::SeqCst, |v| {
            if v > 0 {
                Some(v - 1)
            } else {
                None
            }
        })
        .is_ok()
    {
        return;
    }
    if scaled > 0 {
        thread::sleep(Duration::from_millis(scaled));
    }
}

/// Sleep for a Duration, scaled by the global speed factor.
pub fn sleep_dur(d: Duration) {
    sleep_ms(d.as_millis() as u64);
}

/// Check whether the --exit-after-time deadline has passed; if so, exit.
/// Called by the line-printing helper after a line has been emitted.
pub fn check_deadline() {
    if let Some(deadline) = globals().deadline {
        if Instant::now() >= deadline {
            crate::io::exit_gracefully();
        }
    }
}

