//!
//!
//!
//!
//!
//!
//!
//!
//!
//!
//!
//!
//!
//!
//!
//!
//!
//!
use std::io::Write;

/// Print the given text followed by "\r\n" and flush stdout.
pub fn print_line(text: &str) {
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    handle.write_all(text.as_bytes()).unwrap();
    handle.write_all(b"\r\n").and_then(|_| handle.flush()).unwrap();
    crate::util::check_deadline();
}

/// Print text without a trailing newline and flush stdout.
pub fn print_str(text: &str) {
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    handle.write_all(text.as_bytes()).and_then(|_| handle.flush()).unwrap();
}

/// Print the shutdown message and exit successfully.
pub fn exit_gracefully() -> ! {
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    let _ = handle.write_all(b"Saving work to disk...\n");
    let _ = handle.flush();
    std::process::exit(0);
}

