args.content:
//! Command line argument parsing, mirroring the behavior of the original
//! clap-based CLI (help text, error messages, exit codes).

use std::process::exit;
use std::time::Duration;

pub const VERSION: &str = "genact 1.5.1";

pub const SHELLS: [&str; 5] = ["bash", "elvish", "fish", "powershell", "zsh"];

pub const HELP_TEXT: &str = include_str!("static/help.txt");
pub const MANPAGE: &str = include_str!("static/man.txt");
pub const COMP_BASH: &str = include_str!("static/comp-bash.txt");
pub const COMP_ZSH: &str = include_str!("static/comp-zsh.txt");
pub const COMP_FISH: &str = include_str!("static/comp-fish.txt");
pub const COMP_POWERSHELL: &str = include_str!("static/comp-powershell.txt");
pub const COMP_ELVISH: &str = include_str!("static/comp-elvish.txt");

pub fn possible_values() -> String {
    crate::modules::MODULE_NAMES.join(", ")
}

#[derive(Default)]
pub struct Config {
    pub list_modules: bool,
    pub modules: Vec<String>,
    pub speed: f32,
    pub instant: u64,
    pub inhibit: bool,
    pub exit_after_time: Option<Duration>,
    pub exit_after_modules: Option<u64>,
    pub print_completions: Option<String>,
    pub print_manpage: bool,
}

impl Config {
    fn new() -> Config {
        Config {
            speed: 1.0,
            ..Default::default()
        }
    }
}

const LONG_FLAGS: [&str; 12] = [
    "list-modules",
    "modules",
    "speed-factor",
    "instant-print-lines",
    "inhibit",
    "exit-after-time",
    "exit-after-modules",
    "print-completions",
    "print-manpage",
    "help",
    "version",
    "", // sentinel so trailing comma layout stays simple
];

fn bin_name(argv0: Option<String>) -> String {
    argv0
        .as_deref()
        .and_then(|p| p.rsplit('/').next())
        .unwrap_or("genact")
        .to_string()
}

fn err_tail() -> ! {
    eprintln!("\nFor more information, try '--help'.");
    exit(2);
}

fn err_unexpected_argument(bin: &str, arg: &str) -> ! {
    eprintln!("error: unexpected argument '{arg}' found");
    if let Some(long) = arg.strip_prefix("--") {
        let name = long.split('=').next().unwrap_or(long);
        if let Some(tip) = best_suggestion(name, &LONG_FLAGS[..LONG_FLAGS.len() - 1]) {
            eprintln!("\n  tip: a similar argument exists: '--{tip}'");
        }
    }
    eprintln!("\nUsage: {bin} [OPTIONS]");
    err_tail()
}

fn err_invalid_value(display: &str, value: &str, reason: Option<&str>, possible: Option<&str>, candidates: &[&str]) -> ! {
    match reason {
        Some(r) => eprintln!("error: invalid value '{value}' for '{display}': {r}"),
        None => eprintln!("error: invalid value '{value}' for '{display}'"),
    }
    if let Some(p) = possible {
        eprintln!("  [possible values: {p}]");
        if let Some(tip) = best_suggestion(value, candidates) {
            eprintln!("\n  tip: a similar value exists: '{tip}'");
        }
    }
    err_tail()
}

fn err_missing_value(display: &str, possible: Option<&str>) -> ! {
    eprintln!("error: a value is required for '{display}' but none was supplied");
    if let Some(p) = possible {
        eprintln!("  [possible values: {p}]");
    }
    err_tail()
}

fn err_multiple(display: &str, bin: &str) -> ! {
    eprintln!("error: the argument '{display}' cannot be used multiple times");
    eprintln!("\nUsage: {bin} [OPTIONS]");
    err_tail()
}

fn err_unexpected_value(bin: &str, flag: &str, value: &str) -> ! {
    eprintln!("error: unexpected value '{value}' for '--{flag}' found; no more were expected");
    eprintln!("\nUsage: {bin} --{flag}");
    err_tail()
}

fn print_help(bin: &str) -> ! {
    print!("{}", HELP_TEXT.replacen("executable", bin, 1));
    exit(0);
}

/// Jaro similarity.
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let max_dist = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_match = vec![false; a.len()];
    let mut b_match = vec![false; b.len()];
    let mut matches = 0usize;
    for i in 0..a.len() {
        let start = i.saturating_sub(max_dist);
        let end = (i + max_dist + 1).min(b.len());
        for j in start..end {
            if !b_match[j] && a[i] == b[j] {
                a_match[i] = true;
                b_match[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut j = 0usize;
    for i in 0..a.len() {
        if a_match[i] {
            while !b_match[j] {
                j += 1;
            }
            if a[i] != b[j] {
                transpositions += 1;
            }
            j += 1;
        }
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - transpositions as f64 / 2.0) / m) / 3.0
}

/// Jaro-Winkler similarity with a prefix bonus capped at 4 characters.
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    let prefix = a
        .chars()
        .zip(b.chars())
        .take(4)
        .take_while(|(x, y)| x == y)
        .count();
    j + prefix as f64 * 0.1 * (1.0 - j)
}

fn best_suggestion<'a>(value: &str, candidates: &[&'a str]) -> Option<&'a str> {
    let mut best: Option<(&str, f64)> = None;
    for cand in candidates {
        let conf = jaro_winkler(value, cand);
        if conf > 0.8 && best.map_or(true, |(_, b)| conf > b) {
            best = Some((cand, conf));
        }
    }
    best.map(|(c, _)| c)
}

/// Parse a duration in humantime format (e.g. "2h10min", "300ms", "1.5s").
fn parse_duration(text: &str) -> Result<Duration, String> {
    let chars: Vec<char> = text.chars().collect();
    let mut pos = 0usize;
    let mut total = Duration::ZERO;
    let mut any = false;
    while pos < chars.len() {
        while pos < chars.len() && chars[pos] == ' ' {
            pos += 1;
        }
        if pos >= chars.len() {
            break;
        }
        if !chars[pos].is_ascii_digit() {
            return Err(format!("expected number at {}", pos));
        }
        let mut int_part: u64 = 0;
        while pos < chars.len() && chars[pos].is_ascii_digit() {
            int_part = int_part
                .checked_mul(10)
                .and_then(|v| v.checked_add(chars[pos] as u64 - '0' as u64))
                .ok_or_else(|| "number is too large".to_string())?;
            pos += 1;
        }
        let mut frac_part: u64 = 0;
        let mut frac_digits: u32 = 0;
        if pos < chars.len() && chars[pos] == '.' {
            let dot = pos;
            pos += 1;
            if pos >= chars.len() || !chars[pos].is_ascii_digit() {
                return Err(format!("expected number at {}", dot));
            }
            while pos < chars.len() && chars[pos].is_ascii_digit() {
                if frac_digits < 9 {
                    frac_part = frac_part * 10 + (chars[pos] as u64 - '0' as u64);
                    frac_digits += 1;
                }
                pos += 1;
            }
        }
        while pos < chars.len() && chars[pos] == ' ' {
            pos += 1;
        }
        let unit_start = pos;
        while pos < chars.len() && chars[pos].is_ascii_alphabetic() {
            pos += 1;
        }
        if unit_start == pos {
            return Err("time unit needed, for example 10sec or 10ms".to_string());
        }
        let unit: String = chars[unit_start..pos].iter().collect();
        let nanos_per: u64 = match unit.as_str() {
            "ns" | "nsec" | "nsecs" => 1,
            "us" | "usec" | "usecs" => 1_000,
            "ms" | "msec" | "msecs" => 1_000_000,
            "s" | "sec" | "secs" | "second" | "seconds" => 1_000_000_000,
            "m" | "min" | "mins" | "minute" | "minutes" => 60_000_000_000,
            "h" | "hr" | "hrs" | "hour" | "hours" => 3_600_000_000_000,
            "d" | "day" | "days" => 86_400_000_000_000,
            "w" | "week" | "weeks" => 604_800_000_000_000,
            "M" | "month" | "months" => 2_630_016_000_000_000,
            "y" | "year" | "years" => 31_557_600_000_000_000,
            other => {
                return Err(format!(
                    "unknown time unit {:?}, supported units: ns, us, ms, sec, min, hours, days, weeks, months, years (and few variations)",
                    other
                ))
            }
        };
        let int_nanos = int_part
            .checked_mul(nanos_per)
            .ok_or_else(|| "number is too large".to_string())?;
        let frac_nanos = frac_part * nanos_per / 10u64.pow(frac_digits);
        total = total
            .checked_add(Duration::from_nanos(int_nanos + frac_nanos))
            .ok_or_else(|| "value is too large".to_string())?;
        any = true;
    }
    if !any {
        return Err("expected number at 0".to_string());
    }
    Ok(total)
}

fn is_known_option_token(tok: &str) -> bool {
    if let Some(long) = tok.strip_prefix("--") {
        let name = long.split('=').next().unwrap_or(long);
        return LONG_FLAGS.contains(&name);
    }
    if let Some(shorts) = tok.strip_prefix('-') {
        if let Some(c) = shorts.chars().next() {
            return matches!(c, 'l' | 'm' | 's' | 'i' | 'h' | 'V');
        }
    }
    false
}

pub fn parse() -> Config {
    let mut argv = std::env::args();
    let bin = bin_name(argv.next());
    let args: Vec<String> = argv.collect();
    let mut cfg = Config::new();
    let mut seen_speed = false;
    let mut seen_instant = false;
    let mut seen_list = false;
    let mut seen_inhibit = false;
    let mut seen_eat = false;
    let mut seen_eam = false;
    let mut seen_completions = false;
    let mut seen_manpage = false;

    let modules_pv = possible_values();

    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        i += 1;
        if arg == "--" {
            if i < args.len() {
                err_unexpected_argument(&bin, &args[i].clone());
            }
            break;
        }
        if let Some(long) = arg.strip_prefix("--") {
            let (name, inline): (&str, Option<String>) = match long.find('=') {
                Some(p) => (&long[..p], Some(long[p + 1..].to_string())),
                None => (long, None),
            };
            // Helper to obtain the value for an option.
            macro_rules! take_value {
                ($display:expr, $possible:expr) => {{
                    if let Some(v) = inline.clone() {
                        v
                    } else if i >= args.len() {
                        err_missing_value($display, $possible);
                    } else if args[i].starts_with('-') && args[i].len() > 1 {
                        if is_known_option_token(&args[i]) {
                            err_missing_value($display, $possible);
                        } else {
                            err_unexpected_argument(&bin, &args[i].clone());
                        }
                    } else {
                        let v = args[i].clone();
                        i += 1;
                        v
                    }
                }};
            }
            match name {
                "help" => print_help(&bin),
                "version" => {
                    println!("{VERSION}");
                    exit(0);
                }
                "list-modules" | "inhibit" | "print-manpage" => {
                    if let Some(v) = inline {
                        err_unexpected_value(&bin, name, &v);
                    }
                    let seen = match name {
                        "list-modules" => &mut seen_list,
                        "inhibit" => &mut seen_inhibit,
                        _ => &mut seen_manpage,
                    };
                    if *seen {
                        err_multiple(&format!("--{name}"), &bin);
                    }
                    *seen = true;
                    match name {
                        "list-modules" => cfg.list_modules = true,
                        "inhibit" => cfg.inhibit = true,
                        _ => cfg.print_manpage = true,
                    }
                }
                "modules" => {
                    let v = take_value!("--modules <MODULES>", Some(&modules_pv));
                    if !crate::modules::MODULE_NAMES.contains(&v.as_str()) {
                        err_invalid_value(
                            "--modules <MODULES>",
                            &v,
                            None,
                            Some(&modules_pv),
                            &crate::modules::MODULE_NAMES,
                        );
                    }
                    cfg.modules.push(v);
                }
                "speed-factor" => {
                    if seen_speed {
                        err_multiple("--speed-factor <SPEED_FACTOR>", &bin);
                    }
                    seen_speed = true;
                    let v = take_value!("--speed-factor <SPEED_FACTOR>", None);
                    let f: f32 = match v.parse() {
                        Ok(f) => f,
                        Err(e) => err_invalid_value("--speed-factor <SPEED_FACTOR>", &v, Some(&e.to_string()), None, &[]),
                    };
                    if f < 0.01 {
                        err_invalid_value(
                            "--speed-factor <SPEED_FACTOR>",
                            &v,
                            Some("Speed factor must be larger than 0.01"),
                            None,
                            &[],
                        );
                    }
                    cfg.speed = f;
                }
                "instant-print-lines" => {
                    if seen_instant {
                        err_multiple("--instant-print-lines <INSTANT_PRINT_LINES>", &bin);
                    }
                    seen_instant = true;
                    let v = take_value!("--instant-print-lines <INSTANT_PRINT_LINES>", None);
                    match v.parse::<u64>() {
                        Ok(n) => cfg.instant = n,
                        Err(e) => err_invalid_value("--instant-print-lines <INSTANT_PRINT_LINES>", &v, Some(&e.to_string()), None, &[]),
                    }
                }
                "exit-after-time" => {
                    if seen_eat {
                        err_multiple("--exit-after-time <EXIT_AFTER_TIME>", &bin);
                    }
                    seen_eat = true;
                    let v = take_value!("--exit-after-time <EXIT_AFTER_TIME>", None);
                    match parse_duration(&v) {
                        Ok(d) => cfg.exit_after_time = Some(d),
                        Err(e) => err_invalid_value("--exit-after-time <EXIT_AFTER_TIME>", &v, Some(&e), None, &[]),
                    }
                }
                "exit-after-modules" => {
                    if seen_eam {
                        err_multiple("--exit-after-modules <EXIT_AFTER_MODULES>", &bin);
                    }
                    seen_eam = true;
                    let v = take_value!("--exit-after-modules <EXIT_AFTER_MODULES>", None);
                    match v.parse::<u64>() {
                        Ok(0) => err_invalid_value(
                            "--exit-after-modules <EXIT_AFTER_MODULES>",
                            &v,
                            Some("Must be larger than 0"),
                            None,
                            &[],
                        ),
                        Ok(n) => cfg.exit_after_modules = Some(n),
                        Err(e) => err_invalid_value("--exit-after-modules <EXIT_AFTER_MODULES>", &v, Some(&e.to_string()), None, &[]),
                    }
                }
                "print-completions" => {
                    if seen_completions {
                        err_multiple("--print-completions <shell>", &bin);
                    }
                    seen_completions = true;
                    let pv = SHELLS.join(", ");
                    let v = take_value!("--print-completions <shell>", Some(&pv));
                    if !SHELLS.contains(&v.as_str()) {
                        err_invalid_value("--print-completions <shell>", &v, None, Some(&pv), &SHELLS);
                    }
                    cfg.print_completions = Some(v);
                }
                _ => err_unexpected_argument(&bin, &format!("--{name}")),
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            let cluster: Vec<char> = arg[1..].chars().collect();
            let mut j = 0usize;
            while j < cluster.len() {
                let c = cluster[j];
                j += 1;
                macro_rules! take_short_value {
                    ($display:expr, $possible:expr) => {{
                        let rest: String = cluster[j..].iter().collect();
                        if !rest.is_empty() {
                            j = cluster.len();
                            rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest)
                        } else if i >= args.len() {
                            err_missing_value($display, $possible);
                        } else if args[i].starts_with('-') && args[i].len() > 1 {
                            if is_known_option_token(&args[i]) {
                                err_missing_value($display, $possible);
                            } else {
                                err_unexpected_argument(&bin, &args[i].clone());
                            }
                        } else {
                            let v = args[i].clone();
                            i += 1;
                            v
                        }
                    }};
                }
                match c {
                    'h' => print_help(&bin),
                    'V' => {
                        println!("{VERSION}");
                        exit(0);
                    }
                    'l' => {
                        if seen_list {
                            err_multiple("--list-modules", &bin);
                        }
                        seen_list = true;
                        cfg.list_modules = true;
                    }
                    'm' => {
                        let v = take_short_value!("--modules <MODULES>", Some(&modules_pv));
                        if !crate::modules::MODULE_NAMES.contains(&v.as_str()) {
                            err_invalid_value(
                                "--modules <MODULES>",
                                &v,
                                None,
                                Some(&modules_pv),
                                &crate::modules::MODULE_NAMES,
                            );
                        }
                        cfg.modules.push(v);
                    }
                    's' => {
                        if seen_speed {
                            err_multiple("--speed-factor <SPEED_FACTOR>", &bin);
                        }
                        seen_speed = true;
                        let v = take_short_value!("--speed-factor <SPEED_FACTOR>", None);
                        let f: f32 = match v.parse() {
                            Ok(f) => f,
                            Err(e) => err_invalid_value("--speed-factor <SPEED_FACTOR>", &v, Some(&e.to_string()), None, &[]),
                        };
                        if f < 0.01 {
                            err_invalid_value(
                                "--speed-factor <SPEED_FACTOR>",
                                &v,
                                Some("Speed factor must be larger than 0.01"),
                                None,
                                &[],
                            );
                        }
                        cfg.speed = f;
                    }
                    'i' => {
                        if seen_instant {
                            err_multiple("--instant-print-lines <INSTANT_PRINT_LINES>", &bin);
                        }
                        seen_instant = true;
                        let v = take_short_value!("--instant-print-lines <INSTANT_PRINT_LINES>", None);
                        match v.parse::<u64>() {
                            Ok(n) => cfg.instant = n,
                            Err(e) => err_invalid_value("--instant-print-lines <INSTANT_PRINT_LINES>", &v, Some(&e.to_string()), None, &[]),
                        }
                    }
                    _ => err_unexpected_argument(&bin, &format!("-{c}")),
                }
            }
        } else {
            err_unexpected_argument(&bin, &arg.clone());
        }
    }

    if let Some(shell) = &cfg.print_completions {
        let text = match shell.as_str() {
            "bash" => COMP_BASH,
            "zsh" => COMP_ZSH,
            "fish" => COMP_FISH,
            "powershell" => COMP_POWERSHELL,
            _ => COMP_ELVISH,
        };
        print!("{text}");
        exit(0);
    }
    if cfg.print_manpage {
        print!("{MANPAGE}");
        exit(0);
    }
    if cfg.list_modules {
        println!("Available modules:");
        for m in crate::modules::MODULE_NAMES {
            println!("  {m}");
        }
        exit(0);
    }
    cfg
}

