//! genact - a nonsense activity generator.

mod args;
mod io;
mod modules;
mod rng;
mod util;

use std::time::Instant;

use util::{App, Globals, GLOBALS, INSTANT_REMAINING};

const SIGINT: i32 = 2;
const SIGTERM: i32 = 15;

extern "C" {
    fn signal(signum: i32, handler: extern "C" fn(i32)) -> isize;
    fn write(fd: i32, buf: *const u8, count: usize) -> isize;
    fn _exit(status: i32) -> !;
}

extern "C" fn on_signal(_signum: i32) {
    unsafe {
        let msg = b"Saving work to disk...\n";
        write(1, msg.as_ptr(), msg.len());
        _exit(0);
    }
}

fn main() {
    let cfg = args::parse();

    unsafe {
        signal(SIGINT, on_signal);
        signal(SIGTERM, on_signal);
    }

    let deadline = cfg
        .exit_after_time
        .map(|d| Instant::now() + d);
    let _ = GLOBALS.set(Globals {
        speed: cfg.speed,
        deadline,
    });
    util::INSTANT_REMAINING.store(cfg.instant, std::sync::atomic::Ordering::SeqCst);
    let _ = &INSTANT_REMAINING;

    let mut app = App::new();
    let available: Vec<&str> = if cfg.modules.is_empty() {
        modules::MODULE_NAMES.to_vec()
    } else {
        cfg.modules.iter().map(|s| s.as_str()).collect()
    };

    let mut completed: u64 = 0;
    loop {
        if let Some(max) = cfg.exit_after_modules {
            if completed >= max {
                break;
            }
        }
        let idx = app.rng.gen_range(0, available.len() as u64) as usize;
        modules::run(available[idx], &mut app);
        completed += 1;
    }
    io::exit_gracefully();
}

