new_fn = '''/// Parse a duration in humantime format (e.g. "2h10min", "300ms", "1.5s"),
/// reproducing humantime's error messages.
fn parse_duration(text: &str) -> Result<Duration, String> {
    const TOO_LARGE: &str = "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)";
    if text.is_empty() {
        return Err("value was empty".to_string());
    }
    let chars: Vec<char> = text.chars().collect();
    // Byte offset of each char, for error positions.
    let mut byte_pos: Vec<usize> = Vec::with_capacity(chars.len());
    {
        let mut p = 0usize;
        for c in &chars {
            byte_pos.push(p);
            p += c.len_utf8();
        }
    }
    let len = chars.len();
    let mut pos = 0usize;
    let mut total = Duration::ZERO;
    let mut any = false;
    while pos < len {
        while pos < len && chars[pos] == ' ' {
            pos += 1;
        }
        if pos >= len {
            break;
        }
        if !chars[pos].is_ascii_digit() {
            return Err(format!("expected number at {}", byte_pos[pos]));
        }
        let int_start = pos;
        while pos < len && chars[pos].is_ascii_digit() {
            pos += 1;
        }
        let int_str: String = chars[int_start..pos].iter().collect();
        let int_part: u64 = int_str.parse().map_err(|_| TOO_LARGE.to_string())?;
        let mut frac_str = String::new();
        if pos < len && chars[pos] == '.' {
            let dot = pos;
            if pos + 1 < len && chars[pos + 1].is_ascii_digit() {
                pos += 1;
                while pos < len && chars[pos].is_ascii_digit() {
                    frac_str.push(chars[pos]);
                    pos += 1;
                }
            } else {
                return Err(format!("invalid character at {}", byte_pos[dot]));
            }
        }
        while pos < len && chars[pos] == ' ' {
            pos += 1;
        }
        let unit_start = pos;
        while pos < len && chars[pos].is_alphabetic() {
            pos += 1;
        }
        if unit_start == pos {
            if pos < len {
                return Err(format!("invalid character at {}", byte_pos[pos]));
            }
            return Err(format!(
                "time unit needed, for example {}sec or {}ms",
                int_str, int_str
            ));
        }
        let unit: String = chars[unit_start..pos].iter().collect();
        let nanos_per: u128 = match unit.as_str() {
            "ns" | "nsec" | "nsecs" => 1,
            "us" | "usec" | "usecs" | "\\u{b5}s" | "\\u{3bc}s" => 1_000,
            "ms" | "msec" | "msecs" => 1_000_000,
            "s" | "sec" | "secs" | "second" | "seconds" => 1_000_000_000,
            "m" | "min" | "mins" | "minute" | "minutes" => 60_000_000_000,
            "h" | "hr" | "hrs" | "hour" | "hours" => 3_600_000_000_000,
            "d" | "day" | "days" => 86_400_000_000_000,
            "w" | "week" | "weeks" => 604_800_000_000_000,
            "M" | "month" | "months" => 2_630_016_000_000_000,
            "y" | "year" | "years" => 31_557_600_000_000_000,
            other => {
                return Err(format!(
                    "unknown time unit {:?}, supported units: ns, us/\\u{b5}s, ms, sec, min, hours, days, weeks, months, years (and few variations)",
                    other
                ))
            }
        };
        let int_nanos = (int_part as u128)
            .checked_mul(nanos_per)
            .ok_or_else(|| TOO_LARGE.to_string())?;
        let mut frac_nanos = 0u128;
        if !frac_str.is_empty() {
            let frac_val: u128 = frac_str.parse().map_err(|_| TOO_LARGE.to_string())?;
            let denom = 10u128.pow(frac_str.len() as u32);
            let numerator = frac_val * nanos_per;
            if numerator % denom != 0 {
                return Err(TOO_LARGE.to_string());
            }
            frac_nanos = numerator / denom;
        }
        let item_nanos = int_nanos + frac_nanos;
        let secs = item_nanos / 1_000_000_000;
        if secs > u64::MAX as u128 {
            return Err(TOO_LARGE.to_string());
        }
        total = total
            .checked_add(Duration::new(secs as u64, (item_nanos % 1_000_000_000) as u32))
            .ok_or_else(|| TOO_LARGE.to_string())?;
        any = true;
    }
    if !any {
        return Err("expected number at 0".to_string());
    }
    Ok(total)
}
